# this sitting's one ledger, every claim LABELED (logic/MIDDOT.md's codes — I1 the a fortiori, I2 the gezerah shavah (the verbal analogy), CHECKED IN MIDDOT.md BEFORE
# THEY WERE TYPED; World/step9/CLAIM_LABELS.md), a machine check where the ink allows — every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the
# word's CONSONANTS (the longest piece whole, the floor four code points). Claim IDs DV19-, DV20- and DV21-. Written once (no file may exist; the prefixes checked
# absent from every manifest and unit). Every source cite is checked against the ledger's CITE INDEX before a byte is written, and every CITE INDEX name must be used
# by a claim — the spine's 260 rows distributed by piska (and by row where a piska straddles two claims' verses) over the claims whose verses they head, the eleven
# outside rows with the claims whose verses they cite. Sitting 15's form (write_ch17_manifest.py) over three units. RUN FROM THE REPO ROOT.
import json, os, re, sqlite3, glob, subprocess
ROOT = _ROOT
DATE = '2026-09-24'
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Devarim {r}' for r in rows)
led = open(f'{ROOT}/logic/oral_triage/deu_19_21_shoftim_ki_teitzei_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M))
assert len(CI) == 335, len(CI)
SIF = sorted((int(a), int(b)) for a, b in (s.split(' ')[2].split(':') for s in CI if s.startswith('Sifrei')))
def sifp(*ps): return '; '.join(f'Sifrei Devarim {p}:{r}' for p, r in SIF if p in ps)
def sifr(p, lo, hi): return '; '.join(f'Sifrei Devarim {p}:{r}' for pp, r in SIF if pp == p and lo <= r <= hi)
assert len(SIF) == 271 and sum(1 for p, _ in SIF if 179 <= p <= 221) == 260, (len(SIF), sum(1 for p, _ in SIF if 179 <= p <= 221))
